import assert from 'node:assert/strict';
import {ToyRoomBattle} from '../src/js/toy-room/ToyRoomBattle.js';
import {ARENA_ENEMIES} from '../src/js/toy-room/ArenaEnemies.js';
import {ARENA_TUNING,ArenaPlayerController} from '../src/js/toy-room/ArenaPlayerController.js';
import {arenaEnemyContact} from '../src/js/toy-room/ArenaCombatContact.js';
import {beginArenaPlayerAttack,updateArenaPlayerAnimation} from '../src/js/toy-room/ArenaPlayerAnimation.js';
function make(actor,corner=false) {
 const r={player:{x:430,facing:'right',animTime:0},keysDown:{},gamepadState:{},touchState:{},tutorial:{},furniture:[],clearInput(){this.keysDown={};},story:{state:{swordEquipped:true,attackElapsed:0},attack(){if(this.state.attackElapsed>0)return false;this.state.attackElapsed=18;this.state.attackDirection=r.player.facing==='left'?-1:1;return true;}}};
 const b=new ToyRoomBattle(r,{loadAssets:false});b.tuning=ARENA_TUNING;b.playerController=new ArenaPlayerController();b.presentation={enemies:ARENA_ENEMIES,enemyContact:arenaEnemyContact,onSound(sound){if(sound==='player_attack')beginArenaPlayerAttack(b.state,r.story.state.attackDirection);},updateAnimation(dt){updateArenaPlayerAnimation(b.state,r.player,dt);}};b.activate();if(actor){b.state.index=['train','robot','dinosaur','bear'].indexOf(actor);b.spawn();b.state.transition=null;if(corner){b.state.enemy.x=1440-ARENA_ENEMIES[actor].bodyWidth/2;r.player.x=b.state.enemy.x-b.getEnemyCollisionDistance(actor);}}
 return b;
}
function play({actor,policy='smart',interval=1,dt=1,corner=false,offset=0,restore=false}){
 const b=make(actor,corner);let f=offset; const seen=new Set();const counts={};
 for(;f<18000&&b.state.mode==='BATTLE';f+=dt){
 const s=b.state,e=s.enemy,p=b.room.player,side=e.x>=p.x?1:-1,range=Math.max(b.tuning.swordRange,b.getEnemyCollisionDistance(e.actor)+40);
 b.room.keysDown={};if(!s.transition){
 const toward=side>0?'ArrowRight':'ArrowLeft';
 if(policy==='spam'){b.room.keysDown[toward]=true;if(Math.floor(f)%interval===0)b.attack();}
 else {
 const contact=['Laser Beam','Rocket Punch'].includes(e.attack);
 if(Math.abs(e.x-p.x)>range-12)b.room.keysDown[toward]=true;
 if(e.state==='ATTACK'){
 const end=e.attack==='Toy Leap'?96:72;
 if(contact&&e.elapsed<end)b.room.keysDown.ArrowDown=true;
 if(!contact){const jumpAt=e.attack==='Toy Leap'?60:30;if(e.elapsed>=jumpAt&&e.elapsed<jumpAt+5&&s.jump===0)b.room.keysDown.ArrowUp=true;}
 if(e.elapsed>=end&&s.jump<85)b.attack();
 }else if(e.state!=='HIT'&&e.state!=='ENRAGE'&&Math.abs(e.x-p.x)<range-5&&s.jump<85)b.attack();
 }
 }
 b.update(dt);if(actor==='dinosaur' && f<1000)for(const event of b.state.history){if(!seen.has(event)){seen.add(event);if(['PLAYER_HIT','ENEMY_HIT','SWORD_BLOCKED'].includes(event.event)||event.sound==='dinosaur_rush'||event.sound==='dinosaur_bite')console.log(f,event,e.state,e.elapsed,e.pressureChain,e.attack,Math.abs(e.x-p.x),s.cooldown);}}if(restore&&Math.floor(f)%97===0){const saved=b.snapshot();b.restore(saved);}
 }
 for(const a of ['train','robot','dinosaur','bear'])counts[a]={acertos:b.state.history.filter(x=>x.event==='PLAYER_HIT'&&x.enemy===a).length,danos:b.state.history.filter(x=>x.event==='ENEMY_HIT'&&x.enemy===a).length,bloqueios:b.state.history.filter(x=>x.event==='SWORD_BLOCKED'&&x.enemy===a).length};
 return {actor,policy,interval,dt,corner,offset,restore,resultado:b.state.mode,hp:b.state.player.hp,segundos:+((f-offset)/60).toFixed(2),counts};
}

console.log(play({actor:'dinosaur',policy:'spam',dt:.5,interval:12,offset:7}));
